# Idempotent: Google sign-in button + ?google=<status> messages on the account gate.
import re
p='public/account-ui.js'; s=open(p).read()
if 'account-google' not in s:
    # 1) helpers before authForm
    helpers=("const GOOGLE_MSG={not_invited:'Esa cuenta de Google no tiene invitación. Pide un código y vuelve a intentarlo con él.',not_linked:'Esa cuenta de Google aún no está vinculada a un espacio de EVIE. Entra con tu usuario y vincúlala en Configuración → Acceso con Google.',link_mismatch:'Esa cuenta de Google ya está vinculada a otro espacio. No se mezclaron datos.',expired:'El inicio con Google caducó. Vuelve a intentarlo.',exchange:'Google no completó el acceso. Vuelve a intentarlo.',denied:'Cancelaste el acceso con Google.'};"
             "function googleNotice(){const q=new URLSearchParams(location.search),g=q.get('google');if(!g)return '';q.delete('google');history.replaceState(null,'',location.pathname+(q.toString()?'?'+q:'')+location.hash);if(g==='linked'){setTimeout(()=>window.App?.toast?.('Google quedó vinculado a tu cuenta.','success'),800);return '';}return g==='ok'?'':(GOOGLE_MSG[g]||'No se pudo completar el acceso con Google.');}"
             "async function googleStart(btn,invite){const err=gate.querySelector('#account-error');btn.disabled=true;err.textContent='';try{if(window.evieDesktop?.googleSignIn){await window.evieDesktop.googleSignIn();err.textContent='Se abrió tu navegador. Completa el acceso con Google y vuelve a EVIE.';return;}const r=await EvieAccounts.request('auth/google/start',{method:'POST',body:{mode:'signin',...(invite?{invite}:{})}});if(!/^https:\\/\\//.test(r?.url||''))throw Error('El servidor no devolvió la URL de Google.');location.href=r.url;}catch(x){btn.disabled=false;err.textContent=x.message||'No se pudo iniciar el acceso con Google.';}}\n ")
    s=s.replace(' function authForm(',' '+helpers+'function authForm(',1)
    # 2) button markup after the form
    s=s.replace("</form><div class=\"account-secondary\">",
      "</form>${EvieAccounts.config()?.googleAuth?`<div class=\"account-or\" role=\"separator\"><span>o</span></div><button type=\"button\" class=\"button account-google\" id=\"account-google\"><svg aria-hidden=\"true\" viewBox=\"0 0 48 48\" width=\"18\" height=\"18\"><path fill=\"#FFC107\" d=\"M43.6 20.5H42V20H24v8h11.3C33.7 32.7 29.2 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.4-.4-3.5z\"/><path fill=\"#FF3D00\" d=\"m6.3 14.7 6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 7.9 3.1l5.7-5.7C34 6.1 29.3 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 9.9-2 13.4-5.2l-6.2-5.2C29.2 35.1 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.5H42V20H24v8h11.3c-.8 2.2-2.2 4.2-4.1 5.6l6.2 5.2C37 39.2 44 34 44 24c0-1.3-.1-2.4-.4-3.5z\"/></svg><span>${register?'Crear cuenta con Google':'Entrar con Google'}</span></button><small class=\"account-google-note\">${register?'Usa el código de invitación de arriba. ':''}Google solo comparte tu nombre y correo; EVIE no pide acceso a Gmail ni a Calendar. Si ya tienes usuario, entra con él y vincula Google en Configuración: no se fusionan cuentas por correo.</small>`:''}<div class=\"account-secondary\">",1)
    # 3) handler wiring after the toggle
    s=s.replace("gate.querySelector('#account-other').onclick=()=>authForm(!register);",
      "gate.querySelector('#account-other').onclick=()=>authForm(!register);gate.querySelector('#account-google')?.addEventListener('click',(ev)=>{const inv=form.elements.invite?.value?.trim();if(register&&EvieAccounts.config()?.inviteOnly!==false&&!inv){gate.querySelector('#account-error').textContent='Escribe tu código de invitación antes de continuar con Google.';form.elements.invite.focus();return;}googleStart(ev.currentTarget,inv);});if(EvieAccounts.config()?.passwordLogin===false&&!register){form.hidden=true;}",1)
    # 4) boot: show ?google= message on the login screen
    s=s.replace("if(EvieAccounts.config()?.accountsEnabled&&!EvieAccounts.current()){authForm();return;}",
      "const gmsg=googleNotice();if(EvieAccounts.config()?.accountsEnabled&&!EvieAccounts.current()){authForm(false,gmsg);return;}if(gmsg)setTimeout(()=>window.App?.toast?.(gmsg,'error'),800);",1)
    # 5) desktop: deep-link result reloads into the new session
    s=s.replace(" async function boot(){"," if(window.evieDesktop?.onGoogle)window.evieDesktop.onGoogle((a)=>{if(a.ok)location.reload();else{const el=gate.querySelector('#account-error');if(el)el.textContent=a.error||'No se pudo completar el acceso con Google.';else window.App?.toast?.(a.error,'error');}});\n async function boot(){",1)
    open(p,'w').write(s)
    assert s.count('account-google')>=3 and 'googleNotice();' in s and 'onGoogle(' in s, 'anchors missing'
c='public/evie-hud.css'; t=open(c).read()
if '.account-google' not in t:
    t+="\n/* Acceso con Google */\n.account-or{display:flex;align-items:center;gap:12px;margin:18px 0 12px;color:#b2bed4;font-size:12px}.account-or::before,.account-or::after{content:'';flex:1;height:1px;background:#a8bdff26}\n.account-card .account-google{width:100%;display:flex;align-items:center;justify-content:center;gap:10px;min-height:46px;background:#f4f7ff;color:#1b2440;border:1px solid #dbe3f8;border-radius:10px;font-weight:600}.account-card .account-google:hover:not(:disabled){background:#fff}.account-card .account-google:focus-visible{outline:3px solid #91aaff;outline-offset:3px}\n.account-card .account-google-note{margin-top:10px}\n"
    open(c,'w').write(t)
print('ok')
